<?php

/**
 * Scanner rule boundaries of cphalcon's scanner.re (longest match first, then
 * rule order): numbers, hex, identifiers, bracketed identifiers, strings and
 * their escapes, placeholders, every operator, keyword case and spacing,
 * NUL bytes, control bytes and UTF-8.
 */

declare(strict_types=1);

return [
    // numbers
    'integer'                        => 'SELECT 123 FROM r',
    'integer leading zeros'          => 'SELECT 007 FROM r',
    'hex lower'                      => 'SELECT 0x1f FROM r',
    'hex upper digits'               => 'SELECT 0xABCDEF FROM r',
    'hex bare 0x'                    => 'SELECT 0x FROM r',
    'hex upper X'                    => 'SELECT 0X1F FROM r',
    'hex-like identifier'            => 'SELECT abc FROM r',
    'digits then letters'            => 'SELECT 1abc FROM r',
    'exponent-like'                  => 'SELECT 1e5 FROM r',
    'hex then g'                     => 'SELECT 0x1g FROM r',
    'hex x in middle'                => 'SELECT 1x2 FROM r',
    'double'                         => 'SELECT 1.5 FROM r',
    'double no int'                  => 'SELECT .5 FROM r',
    'double no frac'                 => 'SELECT 5. FROM r',
    'double twice'                   => 'SELECT 1.2.3 FROM r',
    'double then ident'              => 'SELECT 1.5abc FROM r',
    'dot alone'                      => 'SELECT . FROM r',
    'qualified with number'          => 'SELECT a.1 FROM r',
    'limit double'                   => 'SELECT * FROM r LIMIT 1.5',
    'limit negative'                 => 'SELECT * FROM r LIMIT -1',

    // identifiers
    'identifier underscore'          => 'SELECT _a_1 FROM r',
    'identifier leading backslash'   => 'SELECT * FROM \Robots',
    'identifier namespaced'          => 'SELECT * FROM \App\Models\Robots',
    'identifier namespaced no lead'  => 'SELECT * FROM App\Models\Robots',
    'identifier double colon'        => 'SELECT a::int FROM r',
    'identifier trailing colon'      => 'SELECT a: FROM r',
    'identifier double backslash'    => 'SELECT * FROM \\\\Robots',
    'identifier backslash digit'     => 'SELECT * FROM \1Robots',
    'bracket simple'                 => 'SELECT [a] FROM r',
    'bracket space'                  => 'SELECT [a b] FROM r',
    'bracket escaped close'          => 'SELECT [a\]b] FROM r',
    'bracket escaped open'           => 'SELECT [a\[b] FROM r',
    'bracket backslash'              => 'SELECT [a\b] FROM r',
    'bracket empty'                  => 'SELECT [] FROM r',
    'bracket unterminated'           => 'SELECT [abc FROM r',
    'bracket newline'                => "SELECT [a\nb] FROM r",
    'bracket keyword'                => 'SELECT [select] FROM [from]',
    'bracket qualified'              => 'SELECT [a].[b] FROM [r]',
    'bracket utf8'                   => 'SELECT [naïve] FROM r',
    'keyword as identifier'          => 'SELECT select FROM r',
    'keyword prefix identifier'      => 'SELECT selected, fromage, order_id FROM r',

    // strings
    'string single'                  => "SELECT 'abc' FROM r",
    'string double'                  => 'SELECT "abc" FROM r',
    'string empty single'            => "SELECT '' FROM r",
    'string empty double'            => 'SELECT "" FROM r',
    'string escapes'                 => "SELECT 'a\\nb\\rc\\td\\\\e\\'f\\\"g' FROM r",
    'string unknown escapes'         => "SELECT 'a\\%b\\dc\\_d\\0e' FROM r",
    'string double escapes'          => 'SELECT "a\\"b\\\'c\\\\d" FROM r',
    'string raw newline'             => "SELECT 'a\nb' FROM r",
    'string raw tab'                 => "SELECT 'a\tb' FROM r",
    'string other quote inside'      => "SELECT 'a\"b', \"c'd\" FROM r",
    'string backslash backslash n'   => "SELECT 'a\\\\nb' FROM r",
    'string trailing backslash'      => "SELECT 'abc\\' FROM r",
    'string unterminated single'     => "SELECT 'abc FROM r",
    'string unterminated double'     => 'SELECT "abc FROM r',
    'string escape at end'           => "SELECT 'abc\\",
    'string utf8'                    => "SELECT 'żółć €' FROM r",
    'string with nul'                => "SELECT 'a\0b' FROM r",
    'string escaped nul'             => "SELECT 'a\\\0b' FROM r",
    'string escaped newline'         => "SELECT 'a\\\nb' FROM r",

    // placeholders
    'npl'                            => 'SELECT * FROM r WHERE a = ?0',
    'npl multi digit'                => 'SELECT * FROM r WHERE a = ?123',
    'npl bare'                       => 'SELECT * FROM r WHERE a = ?',
    'npl letter'                     => 'SELECT * FROM r WHERE a = ?a',
    'spl'                            => 'SELECT * FROM r WHERE a = :name:',
    'spl dash'                       => 'SELECT * FROM r WHERE a = :a-b:',
    'spl digits'                     => 'SELECT * FROM r WHERE a = :0:',
    'spl empty'                      => 'SELECT * FROM r WHERE a = ::',
    'spl unterminated'               => 'SELECT * FROM r WHERE a = :name',
    'spl space'                      => 'SELECT * FROM r WHERE a = :a b:',
    'bpl'                            => 'SELECT * FROM r WHERE a = {name}',
