    'op #>>'                         => 'SELECT a#>>b FROM r',
    'op #>'                          => 'SELECT a#>b FROM r',
    'op # alone'                     => 'SELECT a # b FROM r',
    'op @@'                          => 'SELECT * FROM r WHERE a@@b',
    'op @>'                          => 'SELECT * FROM r WHERE a@>b',
    'op <@'                          => 'SELECT * FROM r WHERE a<@b',
    'op @ alone'                     => 'SELECT * FROM r WHERE a @ b',
    'op &&'                          => 'SELECT * FROM r WHERE a&&b',
    'op ||'                          => 'SELECT a||b FROM r',
    'op <>'                          => 'SELECT * FROM r WHERE a<>b',
    'op !='                          => 'SELECT * FROM r WHERE a!=b',
    'op ! alone'                     => 'SELECT * FROM r WHERE !a',
    'op <='                          => 'SELECT * FROM r WHERE a<=b',
    'op >='                          => 'SELECT * FROM r WHERE a>=b',
    'op <<'                          => 'SELECT * FROM r WHERE a<<b',
    'op =='                          => 'SELECT * FROM r WHERE a==b',
    'op - >'                         => 'SELECT a- >b FROM r',
    'op &&&'                         => 'SELECT * FROM r WHERE a&&&b',
    'op |||'                         => 'SELECT a|||b FROM r',
    'op ^ ~ & |'                     => 'SELECT a^b, ~a, a&b, a|b FROM r',
    'op no spaces'                   => 'SELECT a+b-c*d/e%f FROM r WHERE(a=1)AND(b<2)',
    'op minus number'                => 'SELECT a-1 FROM r',
    'op semicolon'                   => 'SELECT * FROM r;',
    'op dollar'                      => 'SELECT $a FROM r',
    'op backtick'                    => 'SELECT `a` FROM r',

    // keywords: case and spacing
    'keywords lower'                 => 'select * from r where a = 1 order by a limit 1',
    'keywords mixed'                 => 'SeLeCt * FrOm r WhErE a Is NoT nUlL',
    'not between single space'       => 'SELECT * FROM r WHERE a NOT BETWEEN 1 AND 2',
    'not between lower'              => 'SELECT * FROM r WHERE a not between 1 and 2',
