    'true false null case'           => 'SELECT True, fAlSe, Null FROM r',
    'for update lower'               => 'select * from r for update',

    // whitespace
    'whitespace tabs newlines'       => "SELECT\t*\nFROM\r\nr",
    'whitespace leading trailing'    => "  \n SELECT * FROM r \t\n",
    'whitespace vertical tab'        => "SELECT\v* FROM r",
    'whitespace form feed'           => "SELECT\f* FROM r",

    // NUL and control bytes
    'nul at start'                   => "\0SELECT * FROM r",
    'nul in middle of statement'     => "SELECT * FROM r WHERE\0x",
    'nul after complete statement'   => "SELECT * FROM r\0 garbage",
    'nul at end'                     => "SELECT * FROM r\0",
    'nul after whitespace'           => "SELECT * FROM r WHERE \0",
    'nul inside identifier'          => "SELECT ab\0cd FROM r",
    'control byte'                   => "SELECT \x01 FROM r",
    'control byte at start'          => "\x01SELECT * FROM r",
    'control byte at end'            => "SELECT * FROM r\x01",
    'del byte'                       => "SELECT \x7f FROM r",
    'high byte'                      => "SELECT \xff FROM r",

    // UTF-8
    'utf8 identifier'                => 'SELECT ü FROM r',
    'utf8 after identifier'          => 'SELECT aü FROM r',
    'utf8 in where'                  => 'SELECT * FROM r WHERE name = ü€',
];
